pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let sep_len = sep.len();

    a.into_iter()
        .map(|s| {
            // maxsplit == 0 => no splitting at all.
            if maxsplit == 0 {
                return vec![s];
            }

            // For empty string: required output is a single empty string.
            if s.is_empty() {
                return vec![String::new()];
            }

            let mut parts: Vec<String> = Vec::new();
            let mut end = s.len();
            let mut splits_done: u8 = 0;

            // Repeatedly find the last separator occurrence in s[..end].
            while splits_done < maxsplit {
                let hay = &s[..end];
                if let Some(pos) = hay.rfind(&sep) {
                    // Separator found at [pos, pos+sep_len). Take the suffix after it.
                    let after = &s[(pos + sep_len)..end];
                    parts.push(after.to_string());

                    // Continue searching in the prefix before the separator.
                    end = pos;
                    splits_done += 1;
                } else {
                    break;
                }
            }

            // Push the remaining prefix (could be empty).
            parts.push(s[..end].to_string());

            // We collected from right to left; reverse to get left-to-right order.
            parts.reverse();
            parts
        })
        .collect()
}